{
  "description": "A large quadrupedal creature shown in right-facing profile standing on a small patch of dry, sparsely grassed ground. The front half, including the head, neck, chest and two large outspread wings, is covered in dense eagle-like plumage in golden-brown, dark brown and cream with a hooked beak and yellow eye, while the rear half, including the torso, four legs and long tail, is covered in short tawny lion-like fur with a lighter underbelly. The wings are raised and spread outward from the upper back, showing layered flight feathers darker at the tips. The overall build is muscular and lion-bodied with an eagle head held high.",
  "parts": [
    {
      "part": "head",
      "looks_like": "eagle-like head at the front of the body facing right, with a hooked dark gray beak with a yellow cere at the base, a forward-facing yellow eye with a dark pupil, and golden-brown feathers covering the crown and cheeks"
    ,
      "where": "at the anterior end of the neck, above the feathered chest"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular lion-like legs covered in short tawny fur, lighter on the inner sides and underside, with visible joints and musculature",
      "where": "two forelegs under the chest and two hind legs under the torso, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four large paw-like feet with rounded toes, blunt dark claws and padded soles, light tan fur with darker claws",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long slender lion-like tail covered in short tawny fur ending in a dark brown-black tuft of longer hair",
      "where": "extending from the rear of the torso, curving down and slightly outward to the left side of the image"
    },
    {
      "part": "wings",
      "looks_like": "two very large outspread wings with layered overlapping feathers, golden-brown coverts on the upper surface and darker brown and pale tan flight feathers along the trailing edges and tips",
      "where": "attached to the upper back behind the neck, extending upward and outward to the left and right"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers in shades of golden-brown, dark brown and cream-white, shorter on the head and neck and longer and more layered on the wings and chest",
      "where": "covering the head, neck, chest, and both wings"
    },
    {
      "part": "mane",
      "looks_like": "shaggy ruff of longer, slightly darker feathered fur forming a mane-like fringe around the lower neck and chest",
      "where": "around the front of the neck and upper chest below the head"
    },
    {
      "part": "markings",
      "looks_like": "tawny brown body fur with a paler cream-white underbelly, inner legs and patches on the chest, and darker brown shading along the back and on the wing feathers",
      "where": "over the torso, legs and feathered areas"
    }
  ],
  "attached_objects": [],
  "animals": ["eagle", "lion"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
